cypress_script:
describe('Test Case Listing Functionality', () => {
  it('should display the test cases list', () => {
    cy.visit('https://automationexercise.com/test_cases');
    cy.get('a[href="#collapse1"]').should('be.visible');
    cy.get('a[href="#collapse2"]').should('be.visible');
    cy.get('a[href="#collapse3"]').should('be.visible');
    cy.get('a[href="#collapse4"]').should('be.visible');
    cy.get('a[href="#collapse5"]').should('be.visible');
  });

  it('should not change the URL when clicking an inactive test case', () => {
    cy.visit('https://automationexercise.com/test_cases');
    cy.get('a[href="#collapse1"]').click();
    cy.url().should('eq', 'https://automationexercise.com/test_cases');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Test Case Listing Functionality', () => {
  test('should display the test cases list', async ({ page }) => {
    await page.goto('https://automationexercise.com/test_cases');
    await expect(page.locator('a[href="#collapse1"]')).toBeVisible();
    await expect(page.locator('a[href="#collapse2"]')).toBeVisible();
    await expect(page.locator('a[href="#collapse3"]')).toBeVisible();
    await expect(page.locator('a[href="#collapse4"]')).toBeVisible();
    await expect(page.locator('a[href="#collapse5"]')).toBeVisible();
  });

  test('should not change the URL when clicking an inactive test case', async ({ page }) => {
    await page.goto('https://automationexercise.com/test_cases');
    await page.click('a[href="#collapse1"]');
    await expect(page.url()).toBe('https://automationexercise.com/test_cases');
  });
});
